INSERT dbo.TV_BienThe VALUES (N'tu_hoa_canh',N'Tứ Hóa can Canh: Khoa/Kỵ là Âm/Đồng hay Đồng/Âm',N'["am_dong", "dong_am"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'tu_hoa_nham',N'Hóa Khoa can Nhâm: Tả Phù hay Thiên Phủ',N'["ta_phu", "thien_phu"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'thang_nhuan',N'Sinh tháng nhuận an Mệnh/Thân theo tháng nào',N'["nhu_thang_truoc", "nhu_thang_sau", "nua_dau_truoc_nua_sau_sau"]',NULL,N'lasotuvi dùng ''nhu_thang_truoc'' (bỏ qua cờ nhuận)');
INSERT dbo.TV_BienThe VALUES (N'gio_ty',N'Sinh 23:00–23:59 tính ngày hôm đó hay ngày hôm sau',N'["ngay_hom_sau", "ngay_hom_do"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'mui_gio_lich_su',N'Múi giờ dùng đổi âm lịch: +7 cố định hay theo lịch sử (miền Nam dùng +8 nhiều giai đoạn trước 1975)',N'["utc7_co_dinh", "theo_lich_su_vung"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'gio_mat_troi',N'Dùng giờ đồng hồ hay hiệu chỉnh giờ mặt trời thực theo kinh độ nơi sinh',N'["gio_dong_ho", "gio_mat_troi_thuc"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'chieu_trang_sinh',N'Chiều vòng Tràng Sinh',N'["duong_nam_am_nu_thuan", "nam_thuan_nu_nghich"]',NULL,N'lasotuvi đã đổi sang duong_nam_am_nu_thuan');
INSERT dbo.TV_BienThe VALUES (N'luu_ha_thien_tru',N'Bảng an Lưu Hà (theo can năm) và Thiên Trù can Quý',N'["luu_ha: thai_thu_lang | thien_luong | ngu_hanh", "thien_tru_quy: tuat | hoi"]',N'{"luu_ha": "thai_thu_lang", "thien_tru_quy": "tuat"}',N'Lưu Hà lệch ở Đinh/Canh/Tân: Thái Thứ Lang (lasotuvi, phần mềm lyso.vn) Đinh Thìn, Canh Thân, Tân Mão; Thiên Lương & Việt Viêm Tử Đinh Thân, Canh Thìn; Trình Minh Đức (cách Ngũ Hành) Đinh Thân, Canh Mão, Tân Thìn. Thiên Trù: lasotuvi Quý → Tuất, iztro Quý → Hợi; 9 can còn lại khớp nhau.');
INSERT dbo.TV_BienThe VALUES (N'do_sang',N'Bảng Miếu/Vượng/Đắc/Bình/Hãm',N'["lasotuvi", "thai_thu_lang", "iztro_trung"]',NULL,NULL);
INSERT dbo.TV_BienThe VALUES (N'khoi_viet',N'Vị trí Thiên Khôi/Thiên Việt theo can năm',N'["khau_quyet", "lasotuvi"]',NULL,N'Khẩu quyết phổ biến ''Giáp Mậu Ngưu Dương, Ất Kỷ Thử Hầu, Bính Đinh Trư Kê, Nhâm Quý Thỏ Xà, Canh Tân Mã Hổ''. lasotuvi lệch ở Đinh, Mậu, Canh, Nhâm (khớp 60%). Chọn khẩu quyết. iztro (Trung Hoa) dùng ''Giáp Mậu Canh Ngưu Dương'' → Canh ở Sửu/Mùi, khớp ta 9/10 can.');
INSERT dbo.TV_BienThe VALUES (N'hoa_linh_ty_dau_suu',N'Tuổi Tỵ Dậu Sửu: Hỏa khởi Mão Linh khởi Tuất, hay ngược lại',N'["hoa_mao_linh_tuat", "hoa_tuat_linh_mao"]',NULL,N'Khẩu quyết phổ biến: Hỏa Mão Linh Tuất. lasotuvi đảo ngược. Chọn khẩu quyết.');
INSERT dbo.TV_BienThe VALUES (N'pha_toai',N'Phá Toái theo chi năm',N'["khau_quyet", "lasotuvi"]',NULL,N'Khẩu quyết: Tý Ngọ Mão Dậu → Tỵ; Dần Thân Tỵ Hợi → Dậu; Thìn Tuất Sửu Mùi → Sửu. lasotuvi đổi Tỵ/Dậu.');
INSERT dbo.TV_BienThe VALUES (N'thien_giai',N'Thiên Giải: đếm từ Thân theo tháng có nhảy cung không',N'["khong_nhay", "nhay_cung"]',N'khong_nhay',N'Chính tác giả lasotuvi ghi trong code là không chắc. Chưa có căn cứ quyết định.');
INSERT dbo.TV_BienThe VALUES (N'thien_quy',N'Thiên Quý: từ Văn Khúc (mùng 1) đếm nghịch hay thuận tới ngày sinh, rồi lùi 1',N'["nghich", "thuan"]',N'nghich',N'lasotuvi: nghịch (đối xứng với Ân Quang đếm thuận từ Văn Xương). iztro: thuận, khớp 200/200 mẫu với công thức Văn Khúc + (ngày−2). Chưa tìm được trang VN ghi rõ cách an.');
INSERT dbo.TV_BienThe VALUES (N'hoa_linh_chieu',N'Chiều an Hỏa/Linh theo giờ',N'["theo_am_duong_nam_nu", "luon_thuan"]',N'theo_am_duong_nam_nu',N'Phái VN (lasotuvi): Dương Nam/Âm Nữ Hỏa thuận Linh nghịch, ngược lại thì đảo. iztro (Trung Hoa): cả hai luôn thuận — khớp 200/200 mẫu. Chưa làm profile, chỉ ghi nhận.');
