INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Dieu_Kien_Pha,Ket_Luan,Ket_Luan_Pha,Diem,Diem_Pha,Linh_Vuc,Trang_Thai) VALUES (N'CC02',N'cach_cuc',N'Quân Thần Khánh Hội',N'Mệnh',N'{"all": [{"co": "Tử Vi"}, {"co_ca": ["Tả Phù", "Hữu Bật"], "o": "tam_phuong"}]}',N'{"any": [{"dem": {"nhom": "tu_sat", "toi_thieu": 1}}, {"co_mot": ["Địa Không", "Địa Kiếp"]}]}',N'Vua có bầy tôi: lãnh đạo được người, không đại quý cũng đại phú.',N'Gặp sát tinh/Không Kiếp: không hợp cách, có danh mà thiếu thực.',3,0,N'su_nghiep,quyen',N'da_gan_nguon');
